MAX_CHARS = 2000

output = []

for item in _items:
    article = item["json"]

    article_id = article.get("id")
    question = (article.get("title") or "").strip()
    answer = (article.get("content") or "").strip()
    category_id = article.get("category_id")

    if not question or not answer:
        continue

    # Complete FAQ
    full_text = f"Question: {question}\n\nAnswer: {answer}"

    # Case 1: FAQ is short enough → one chunk
    if len(full_text) <= MAX_CHARS:
        output.append({
            "json": {
                "article_id": article_id,
                "chunk_index": 0,
                "section_title": None,
                "content": full_text,
                "category_id": category_id
            }
        })

        continue

    # Case 2: FAQ is long → split the answer by paragraphs
    paragraphs = [
        p.strip()
        for p in answer.split("\n\n")
        if p.strip()
    ]

    current_chunk = ""
    chunk_index = 0

    for paragraph in paragraphs:

        candidate = (
            f"{current_chunk}\n\n{paragraph}"
            if current_chunk
            else paragraph
        )

        max_answer_size = MAX_CHARS - len(question) - 20

        if len(candidate) <= max_answer_size:
            current_chunk = candidate

        else:
            # Save current chunk
            if current_chunk:
                output.append({
                    "json": {
                        "article_id": article_id,
                        "chunk_index": chunk_index,
                        "section_title": None,
                        "content": (
                            f"Question: {question}\n\n"
                            f"Answer: {current_chunk}"
                        ),
                        "category_id": category_id
                    }
                })

                chunk_index += 1

            current_chunk = paragraph

    # Save final chunk
    if current_chunk:
        output.append({
            "json": {
                "article_id": article_id,
                "chunk_index": chunk_index,
                "section_title": None,
                "content": (
                    f"Question: {question}\n\n"
                    f"Answer: {current_chunk}"
                ),
                "category_id": category_id
            }
        })

return output

